import leetcode.medium.OnlineStockSpan;
import org.junit.Assert;
import org.junit.Test;

public class OnlineStockSpanTest {

    @Test
    public void nextSinglePriceTest() {
        OnlineStockSpan onlineStockSpan = new OnlineStockSpan();
        int result = onlineStockSpan.next(10);
        Assert.assertEquals(1, result);
    }

    @Test
    public void nextMultiplePricesInAscendingOrderTest() {
        OnlineStockSpan onlineStockSpan = new OnlineStockSpan();
        onlineStockSpan.next(10);
        onlineStockSpan.next(20);
        int result = onlineStockSpan.next(30);
        Assert.assertEquals(3, result);
    }

    @Test
    public void nextMultiplePricesInDescendingOrderTest() {
        OnlineStockSpan onlineStockSpan = new OnlineStockSpan();
        onlineStockSpan.next(30);
        onlineStockSpan.next(20);
        int result = onlineStockSpan.next(10);
        Assert.assertEquals(1, result);
    }

    @Test
    public void nextMultiplePricesInUnorderedTest() {
        OnlineStockSpan onlineStockSpan = new OnlineStockSpan();
        onlineStockSpan.next(20);
        onlineStockSpan.next(30);
        onlineStockSpan.next(10);
        int result = onlineStockSpan.next(40);
        Assert.assertEquals(4, result);
    }

    @Test
    public void calculateSpansEmptyTest() {
        OnlineStockSpan onlineStockSpan = new OnlineStockSpan();
        int[] result = onlineStockSpan.calculateSpans(new int[]{});
        Assert.assertArrayEquals(new int[]{}, result);
    }

    @Test
    public void calculateSpansSinglePriceTest() {
        OnlineStockSpan onlineStockSpan = new OnlineStockSpan();
        int[] result = onlineStockSpan.calculateSpans(new int[]{10});
        Assert.assertArrayEquals(new int[]{1}, result);
    }

    @Test
    public void calculateSpansMultiplePricesInAscendingOrderTest() {
        OnlineStockSpan onlineStockSpan = new OnlineStockSpan();
        int[] result = onlineStockSpan.calculateSpans(new int[]{10, 20, 30});
        Assert.assertArrayEquals(new int[]{1, 2, 3}, result);
    }

    @Test
    public void calculateSpansMultiplePricesInDescendingOrderTest() {
        OnlineStockSpan onlineStockSpan = new OnlineStockSpan();
        int[] result = onlineStockSpan.calculateSpans(new int[]{30, 20, 10});
        Assert.assertArrayEquals(new int[]{1, 1, 1}, result);
    }

    @Test
    public void calculateSpansMultiplePricesInUnorderedTest() {
        OnlineStockSpan onlineStockSpan = new OnlineStockSpan();
        int[] result = onlineStockSpan.calculateSpans(new int[]{20, 30, 10, 40});
        Assert.assertArrayEquals(new int[]{1, 2, 1, 4}, result);
    }
}
